 53	package shop;
 54	
 55	import java.time.Clock;
 56	import java.time.Duration;
 57	import java.time.Instant;
 58	import java.time.format.DateTimeParseException;
 59	import java.time.temporal.ChronoUnit;
 60	import java.util.List;
 61	import java.util.UUID;
 62	
 63	class OrderService {
 64	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 65	
 66	    private final Store store;
 67	    private final PricingService pricing;
 68	    private final Clock clock;
 69	    private final List<OrderEffect> effects = List.of(new StockEffect(), new ClubCreditEffect(), new NotificationEffect());
 70	
 71	    OrderService(Store store, PricingService pricing, Clock clock) {
 72	        this.store = store;
 73	        this.pricing = pricing;
 74	        this.clock = clock;
 75	    }
 76	
 77	    Summary summary(CheckoutRequest request) {
 78	        return store.transaction(tx -> pricing.calculate(request, tx));
 79	    }
 80	
 81	    Order register(CheckoutRequest request) {
 82	        return store.transaction(tx -> {
 83	            Summary summary = pricing.calculate(request, tx);
 84	            List<OrderItem> items = request.items().stream()
 85	                    .map(i -> new OrderItem(i.sku(), i.quantity())).toList();
 86	            Order order = new Order(UUID.randomUUID().toString(), request.cpf(), request.email(),
 87	                    OrderStatus.AWAITING_PAYMENT, clock.instant().truncatedTo(ChronoUnit.SECONDS), summary, items,
 88	                    null, null, null);
 89	            tx.ensureCustomer(request.cpf(), request.email());
 90	            tx.insertOrder(order);
 91	            return order;
 92	        });
 93	    }
 94	
 95	    Order get(String id) {
 96	        return store.transaction(tx -> tx.findOrder(id).orElseThrow(OrderService::notFound));
 97	    }
 98	
 99	    /** Resultado de uma transação que pode ter confirmado algo e mesmo assim recusar o pedido. */
100	    private record Outcome(Order order, ApiException error) {}
101	
102	    Order pay(String id, String transactionId, String paidAtText) {
103	        Outcome outcome = store.transaction(tx -> {
104	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
105	            Instant paidAt = parseInstant(paidAtText);
106	            if (transactionId == null || transactionId.isBlank() || paidAt == null) {
107	                throw ApiException.unprocessable("INVALID_ORDER");
108	            }
109	            PaymentRecord previous = tx.findPayment(id, transactionId).orElse(null);
110	            if (previous != null) {
111	                return previous.errorCode() == null
112	                        ? new Outcome(order, null)
113	                        : new Outcome(null, new ApiException(previous.errorCode(), previous.httpStatus()));
114	            }
115	            if (order.status() != OrderStatus.AWAITING_PAYMENT) throw ApiException.conflict("OPERATION_NOT_ALLOWED");
116	
117	            if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
118	                return reject(tx, order, transactionId, "ORDER_EXPIRED");
119	            }
120	            try {
121	                for (OrderEffect e : effects) e.onPaid(tx, order);
122	            } catch (ApiException e) {
123	                return reject(tx, order, transactionId, e.code());
124	            }
125	            Order paid = order.paid(transactionId, paidAt);
126	            tx.updateOrder(paid);
127	            tx.savePayment(id, transactionId, new PaymentRecord(null, 200));
128	            return new Outcome(paid, null);
129	        });
130	        if (outcome.error() != null) throw outcome.error();
131	        return outcome.order();
132	    }
133	
134	    private Outcome reject(Tx tx, Order order, String transactionId, String code) {
135	        cancelInTx(tx, order, false);
136	        tx.savePayment(order.id(), transactionId, new PaymentRecord(code, 409));
137	        return new Outcome(null, ApiException.conflict(code));
138	    }
139	
140	    Order ship(String id, String trackingCode) {
141	        return store.transaction(tx -> {
142	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
143	            if (trackingCode == null || trackingCode.isBlank()) throw ApiException.unprocessable("INVALID_ORDER");
144	            if (order.status() != OrderStatus.PAID) throw ApiException.conflict("OPERATION_NOT_ALLOWED");
145	            Order shipped = order.shipped(trackingCode);
146	            tx.updateOrder(shipped);
147	            for (OrderEffect e : effects) e.onShipped(tx, shipped);
148	            return shipped;
149	        });
150	    }
151	
152	    Order deliver(String id) {
153	        return store.transaction(tx -> {
154	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
155	            if (order.status() != OrderStatus.SHIPPED) throw ApiException.conflict("OPERATION_NOT_ALLOWED");
156	            Order delivered = order.withStatus(OrderStatus.DELIVERED);
157	            tx.updateOrder(delivered);
158	            return delivered;
159	        });
160	    }
161	
162	    Order cancel(String id) {
163	        return store.transaction(tx -> {
164	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
165	            if (order.status() != OrderStatus.AWAITING_PAYMENT && order.status() != OrderStatus.PAID) {
166	                throw ApiException.conflict("OPERATION_NOT_ALLOWED");
167	            }
168	            return cancelInTx(tx, order, order.status() == OrderStatus.PAID);
169	        });
170	    }
171	
172	    private Order cancelInTx(Tx tx, Order order, boolean wasPaid) {
173	        Order cancelled = order.withStatus(OrderStatus.CANCELLED);
174	        if (wasPaid) {
175	            for (OrderEffect e : effects) e.onPaidOrderCancelled(tx, order);
176	        }
177	        tx.updateOrder(cancelled);
178	        for (OrderEffect e : effects) e.onCancelled(tx, cancelled);
179	        return cancelled;
180	    }
181	
182	    private static Instant parseInstant(String text) {
183	        if (text == null) return null;
184	        try {
185	            return Instant.parse(text);
186	        } catch (DateTimeParseException e) {
187	            return null;
188	        }
189	    }
190	
191	    private static ApiException notFound() {
192	        return ApiException.notFound("ORDER_NOT_FOUND");
193	    }
194	}
195	package shop;
196	
197	import java.util.List;
198	
199	/**
200	 * Consequências das mudanças de situação do pedido. Novas consequências (SMS, cashback...) são novas
201	 * implementações adicionadas à lista em {@link OrderService}.
202	 */
203	interface OrderEffect {
204	    /** Pagamento confirmado. Pode recusar (ApiException) desde que ainda não tenha alterado nada. */
205	    default void onPaid(Tx tx, Order order) {}
206	
207	    /** Pedido já pago foi cancelado: desfaz o que {@link #onPaid} fez. */
208	    default void onPaidOrderCancelled(Tx tx, Order order) {}
209	
210	    /** Qualquer cancelamento. */
211	    default void onCancelled(Tx tx, Order order) {}
212	
213	    default void onShipped(Tx tx, Order order) {}
214	}
215	
216	class StockEffect implements OrderEffect {
217	    @Override
218	    public void onPaid(Tx tx, Order order) {
219	        List<String> skus = order.items().stream().map(OrderItem::sku).toList();
220	        List<Product> locked = tx.lockProducts(skus);
221	        for (OrderItem item : order.items()) {
222	            Product p = locked.stream().filter(x -> x.sku().equals(item.sku())).findFirst().orElse(null);
223	            if (p == null || p.stock() < item.quantity()) throw ApiException.conflict("INSUFFICIENT_STOCK");
224	        }
225	        for (OrderItem item : order.items()) tx.addStock(item.sku(), -item.quantity());
226	    }
227	
228	    @Override
229	    public void onPaidOrderCancelled(Tx tx, Order order) {
230	        tx.lockProducts(order.items().stream().map(OrderItem::sku).toList());
231	        for (OrderItem item : order.items()) tx.addStock(item.sku(), item.quantity());
232	    }
233	}
234	
235	class ClubCreditEffect implements OrderEffect {
236	    @Override
237	    public void onPaid(Tx tx, Order order) {
238	        tx.addCredit(order.cpf(), order.summary().nextPurchaseCredit());
239	    }
240	
241	    @Override
242	    public void onPaidOrderCancelled(Tx tx, Order order) {
243	        tx.addCredit(order.cpf(), order.summary().nextPurchaseCredit().negate());
244	    }
245	}
246	
247	class NotificationEffect implements OrderEffect {
248	    @Override
249	    public void onPaid(Tx tx, Order order) {
250	        tx.addNotification(order.cpf(), NotificationType.PAYMENT_APPROVED, order.id());
251	    }
252	
253	    @Override
254	    public void onCancelled(Tx tx, Order order) {
255	        tx.addNotification(order.cpf(), NotificationType.ORDER_CANCELLED, order.id());
256	    }
257	
258	    @Override
259	    public void onShipped(Tx tx, Order order) {
260	        tx.addNotification(order.cpf(), NotificationType.ORDER_SHIPPED, order.id());
261	    }
262	}
263	package shop;
264	
265	import java.math.BigDecimal;
266	import java.util.Collection;
267	import java.util.List;
268	import java.util.Optional;
269	import java.util.function.Function;
270	
271	/** Armazenamento: toda operação roda dentro de uma transação. */
272	interface Store {
273	    <T> T transaction(Function<Tx, T> work);
274	}
275	
276	/**
277	 * Operações dentro de uma transação. Ordem de travas usada por todos os fluxos, para evitar deadlock:
278	 * pedido, depois produtos (por SKU), depois cliente.
279	 */
280	interface Tx {
281	    Optional<Product> findProduct(String sku);
282	
283	    /** Trava os produtos para alteração, em ordem de SKU, e devolve o estado atual. */
284	    List<Product> lockProducts(Collection<String> skus);
285	
286	    void addStock(String sku, int delta);
287	
288	    Optional<Order> findOrder(String id);
289	
290	    Optional<Order> lockOrder(String id);
291	
292	    void insertOrder(Order order);
293	
294	    void updateOrder(Order order);
295	
296	    /** Existe pedido pago, enviado ou entregue para o CPF? */
297	    boolean hasFulfilledOrder(String cpf);
298	
299	    void ensureCustomer(String cpf, String email);
300	
301	    Optional<Customer> findCustomer(String cpf);
302	
303	    void addCredit(String cpf, BigDecimal delta);
304	
305	    Optional<PaymentRecord> findPayment(String orderId, String transactionId);
306	
307	    void savePayment(String orderId, String transactionId, PaymentRecord record);
308	
309	    Notification addNotification(String cpf, NotificationType type, String orderId);
310	
311	    List<Notification> notifications(String cpf);
312	
313	    Optional<Notification> markRead(long id);
314	}
315	
316	final class Catalog {
317	    private Catalog() {}
318	
319	    static List<Product> initial() {
320	        return List.of(
321	                new Product("CAM-001", "Camiseta básica", new BigDecimal("79.90"), new BigDecimal("0.30"), 50, false),
322	                new Product("TEN-001", "Tênis corrida", new BigDecimal("249.90"), new BigDecimal("1.20"), 10, false),
323	                new Product("FON-001", "Fone sem fio", new BigDecimal("199.90"), new BigDecimal("0.25"), 5, false),
324	                new Product("MEI-001", "Meia esportiva", new BigDecimal("19.90"), new BigDecimal("0.10"), 100, false),
325	                new Product("JAQ-001", "Jaqueta corta-vento", new BigDecimal("389.90"), new BigDecimal("0.80"), 3, false),
326	                new Product("MOC-001", "Mochila urbana", new BigDecimal("159.90"), new BigDecimal("0.90"), 1, false),
327	                new Product("BON-001", "Boné aba reta", new BigDecimal("59.90"), new BigDecimal("0.15"), 0, false),
328	                new Product("REL-001", "Relógio digital", new BigDecimal("129.90"), new BigDecimal("0.20"), 8, true));
329	    }
