    14	/** Armazenamento em memória, usado nos testes (sem banco). Uma transação por vez. */
    15	class MemoryStore implements Store {
    16	    private final ReentrantLock lock = new ReentrantLock();
    17	    private final Map<String, Product> products = new HashMap<>();
    18	    private final Map<String, Order> orders = new HashMap<>();
    19	    private final Map<String, Customer> customers = new HashMap<>();
    20	    private final Map<String, PaymentRecord> payments = new HashMap<>();
    21	    private final List<Notification> notifications = new ArrayList<>();
    22	
    23	    MemoryStore() {
    24	        for (Product p : Catalog.initial()) products.put(p.sku(), p);
    25	    }
    26	
    27	    @Override
    28	    public <T> T transaction(Function<Tx, T> work) {
    29	        lock.lock();
    30	        try {
    31	            return work.apply(new MemoryTx());
    32	        } finally {
    33	            lock.unlock();
    34	        }
    35	    }
    36	
    37	    private final class MemoryTx implements Tx {
    38	        public Optional<Product> findProduct(String sku) {
    39	            return Optional.ofNullable(products.get(sku));
    40	        }
    41	
    42	        public List<Product> lockProducts(Collection<String> skus) {
    43	            List<Product> result = new ArrayList<>();
    44	            for (String sku : new TreeSet<>(skus)) {
    45	                Product p = products.get(sku);
    46	                if (p != null) result.add(p);
    47	            }
    48	            return result;
    49	        }
    50	
    51	        public void addStock(String sku, int delta) {
    52	            Product p = products.get(sku);
    53	            if (p.stock() + delta < 0) throw new IllegalStateException("negative stock");
    54	            products.put(sku, new Product(sku, p.name(), p.price(), p.weightKg(), p.stock() + delta, p.discontinued()));
    55	        }
    56	
    57	        public Optional<Order> findOrder(String id) {
    58	            return Optional.ofNullable(orders.get(id));
    59	        }
    60	
    61	        public Optional<Order> lockOrder(String id) {
    62	            return findOrder(id);
    63	        }
    64	
    65	        public void insertOrder(Order order) {
    66	            orders.put(order.id(), order);
    67	        }
    68	
    69	        public void updateOrder(Order order) {
    70	            orders.put(order.id(), order);
    71	        }
    72	
    73	        public boolean hasFulfilledOrder(String cpf) {
    74	            return orders.values().stream().anyMatch(o -> o.cpf().equals(cpf)
    75	                    && (o.status() == OrderStatus.PAID || o.status() == OrderStatus.SHIPPED
    76	                    || o.status() == OrderStatus.DELIVERED));
    77	        }
    78	
    79	        public void ensureCustomer(String cpf, String email) {
    80	            customers.putIfAbsent(cpf, new Customer(cpf, Money.ZERO));
    81	        }
    82	
    83	        public Optional<Customer> findCustomer(String cpf) {
    84	            return Optional.ofNullable(customers.get(cpf));
    85	        }
    86	
