    88	            Customer c = customers.get(cpf);
    89	            customers.put(cpf, new Customer(cpf, Money.round(c.creditBalance().add(delta))));
    90	        }
    91	
    92	        public Optional<PaymentRecord> findPayment(String orderId, String transactionId) {
    93	            return Optional.ofNullable(payments.get(orderId + "|" + transactionId));
    94	        }
    95	
    96	        public void savePayment(String orderId, String transactionId, PaymentRecord record) {
    97	            payments.put(orderId + "|" + transactionId, record);
    98	        }
    99	
   100	        public Notification addNotification(String cpf, NotificationType type, String orderId) {
   101	            Notification n = new Notification(notifications.size() + 1L, cpf, type, orderId, NotificationStatus.NEW);
   102	            notifications.add(n);
   103	            return n;
   104	        }
   105	
   106	        public List<Notification> notifications(String cpf) {
   107	            return notifications.stream().filter(n -> n.cpf().equals(cpf)).toList();
   108	        }
   109	
   110	        public Optional<Notification> markRead(long id) {
   111	            if (id < 1 || id > notifications.size()) return Optional.empty();
   112	            Notification n = notifications.get((int) id - 1);
   113	            Notification read = new Notification(n.id(), n.cpf(), n.type(), n.orderId(), NotificationStatus.READ);
   114	            notifications.set((int) id - 1, read);
   115	            return Optional.of(read);
   116	        }
   117	    }
   118	}
